import { ArcHandle, Jwk, Key, ScanHandle, SessionHandle, StoreHandle } from '@openwallet-foundation/askar-shared';
import type { ByteBufferType, SecretBufferType } from './structures';
export type Callback = (err: number) => void;
export type CallbackWithResponse = (err: number, response: string) => void;
type Argument = Record<string, unknown> | ArcHandle | StoreHandle | SessionHandle | ScanHandle | unknown[] | Date | Uint8Array | SerializedArgument | boolean | Jwk | Key;
type SerializedArgument = string | number | Callback | CallbackWithResponse | ByteBufferType | Uint8Array | ByteBufferType | SecretBufferType | null;
export type SerializedOptions<Type> = {
    [Property in keyof Type]: Type[Property] extends string ? string : Type[Property] extends number | boolean | Date | StoreHandle | SessionHandle | ScanHandle ? number : Type[Property] extends Record<string, unknown> | unknown[] ? string : Type[Property] extends Uint8Array | Key | ArcHandle | Jwk ? Uint8Array : Type[Property] extends Callback ? Callback : Type[Property] extends CallbackWithResponse ? CallbackWithResponse : Type[Property] extends boolean | undefined ? number | undefined : Type[Property] extends unknown[] | undefined ? string | undefined : Type[Property] extends Record<string, unknown> | undefined ? string | undefined : Type[Property] extends Date | undefined ? number | undefined : Type[Property] extends string | undefined ? string | undefined : Type[Property] extends number | undefined ? number | undefined : Type[Property] extends Uint8Array | undefined ? Uint8Array | undefined : unknown;
};
declare const serializeArguments: <T extends Record<string, Argument> = Record<string, Argument>>(args: T) => SerializedOptions<T>;
export { serializeArguments };
